def pad_to_length(lst, n, pad):
    if len(lst) < n:
        return lst + [pad] * (n - len(lst))
    else:
        return lst[:n]

def pad_left_to_length(lst, n, pad):
    if len(lst) < n:
        return [pad] * (n - len(lst)) + lst
    else:
        return lst[len(lst) - n:]

def count_occurrences_map(lst):
    result = {}
    for x in lst:
        result[x] = result.get(x, 0) + 1
    return result

def first_unique_element(lst):
    from collections import Counter
    counts = Counter(lst)
    for x in lst:
        if counts[x] == 1:
            return x
    return None

def last_unique_element(lst):
    from collections import Counter
    counts = Counter(lst)
    for x in reversed(lst):
        if counts[x] == 1:
            return x
    return None

def merge_alternating_reverse(a, b):
    rev_b = list(reversed(b))
    result = []
    n = min(len(a), len(rev_b))
    for i in range(n):
        result.append(a[i])
        result.append(rev_b[i])
    if len(a) > n:
        result.extend(a[n:])
    else:
        result.extend(rev_b[n:])
    return result

def count_leading_equal(lst):
    if not lst:
        return 0
    first = lst[0]
    count = 0
    for x in lst:
        if x == first:
            count += 1
        else:
            break
    return count

def count_trailing_equal(lst):
    if not lst:
        return 0
    last = lst[-1]
    count = 0
    for x in reversed(lst):
        if x == last:
            count += 1
        else:
            break
    return count

def remove_adjacent_duplicate_pairs(lst):
    stack = []
    for x in lst:
        if stack and stack[-1] == x:
            stack.pop()
        else:
            stack.append(x)
    return stack

def find_missing_numbers(lst, lo, hi):
    present = set(x for x in lst if lo <= x <= hi)
    return [i for i in range(lo, hi + 1) if i not in present]

def alternating_sum(lst):
    total = 0
    for i, x in enumerate(lst):
        if i % 2 == 0:
            total += x
        else:
            total -= x
    return total

def chunk_by_predicate_change(lst):
    if not lst:
        return []
    result = []
    current = [lst[0]]
    for x in lst[1:]:
        if x % 2 == current[-1] % 2:
            current.append(x)
        else:
            result.append(current)
            current = [x]
    result.append(current)
    return result

def shift_and_fill(lst, k, fill):
    n = len(lst)
    if k >= n:
        return [fill] * n
    return [fill] * k + lst[:n - k]

def interleave_chunks(a, b, k):
    result = []
    i, j = 0, 0
    turn = 'a'
    while i < len(a) or j < len(b):
        if turn == 'a':
            if i < len(a):
                result.extend(a[i:i + k])
                i += k
            turn = 'b'
        else:
            if j < len(b):
                result.extend(b[j:j + k])
                j += k
            turn = 'a'
    return result
